# 第 8 批：卦 64（未济）

HEXAGRAMS = {
  "64": {"zh": "未济卦火在水上，事未成。它讲未成之理——未济不是终结，慎终如始；小狐渡河，快到岸却湿了尾巴，此时无利。", "en": "Weiji is fire over water — the task unfinished. It's about the unfinished: Weiji isn't the end; be careful at the close as at the start. The little fox almost crosses but wets its tail — nothing favorable.", "ja": "未済は水の上に火。事がまだ成らない。未成の道理を表す——未済は終わりではなく、終わりを初めのように慎む。小狐が渡りかけて尾を濡らす。利するところなし。"},
}

LINES = {
  "64-0": {"zh": "你在最底下，是未济的开始，柔弱不能渡，所以湿了尾巴。才不足以济而强济，进就困——量己而后动，是慎。", "en": "You're at the bottom, the start of Weiji — too soft to cross, so you wet your tail. Ability too small yet forcing a crossing, you're stuck. Know your measure before acting: that's care.", "ja": "一番下にいて、未済の初め。柔弱で渡れず、尾を濡らす。才が足りないのに無理に渡れば進みは困る。己を量ってから動くのが慎みだ。"},
  "64-1": {"zh": "你在下卦正中，刚中而能自止，不轻进。未济之时，进不可骤——刚中而能止，其行也正。", "en": "You're at the center of the lower trigram, strong and centered, able to stop yourself, not advancing rashly. In Weiji, advance can't be sudden. Strong-centered and able to stop, your conduct is right.", "ja": "下卦の中央にいて、剛中で自ら止められ、軽く進まない。未済の時は進みを急げない。剛中で止められれば、その行いは正しい。"},
  "64-2": {"zh": "你在下卦最上面，不中不正，不能自济却可以因人。柔而不中，独往则困——能附于刚者，就可共济。", "en": "You're at the top of the lower trigram — off-center and improper — unable to cross alone but able to rely on another. Soft and off-center, going alone is hard. Attaching to the strong lets you cross together.", "ja": "下卦の最上部にいて、中も正も外れ、独りでは渡れず人に因れる。柔で中を外れれば、独往は困る。剛に付けば共に渡れる。"},
  "64-3": {"zh": "你在上卦下面，刚而居柔，以刚济难而持之以久。未济而能济，在于刚而能久——久则功成而有赏。", "en": "You're below the upper trigram, strong in a soft place — crossing difficulty with firmness and persisting. Overcoming the unfinished lies in firmness that lasts. Lasting, you succeed and are rewarded.", "ja": "上卦の下にいて、剛で柔の位にあり、剛をもって難を済み、久しく続ける。未済を済めるのは剛で長く続けられるから。久しければ功は成り褒美がある。"},
  "64-4": {"zh": "你在尊位，柔中而应九二，以柔中之德济难。有其德，其光自着——虚中而任刚，其孚及于人。", "en": "You're in the place of honor, soft and centered, matched with the second line — crossing difficulty with soft-centered virtue. With virtue, your light shows itself. Empty within and appointing the strong, your faith reaches people.", "ja": "尊い位にいて、柔らかく中を得て九二に応じ、柔中の徳で難を済む。徳があればその光は自ずと現れる。中を虚しくして剛を任せれば、その孚は人に及ぶ。"},
  "64-5": {"zh": "你到了卦的顶，是未济的终点，可以有为而自乐，过了就失。未济之终，可与其人共乐——然乐不可极，极则并所守而失。", "en": "You're at the top of the hexagram, Weiji at its end — able to act and rejoicing, but excess loses it. At the end of Weiji, you can rejoice with your people. Yet joy can't be maxed out; at the extreme you lose even your grip.", "ja": "卦の頂点にいて、未済の終わり。為すことができて自ら喜ぶが、過ぎれば失う。未済の終わりはその人と共に喜べる。ただ喜びは極めてはならず、極めれば守るものまで失う。"},
}
